sed -n 1,24p e2e/flashcards-themes.visual.spec.ts | grep -n 'goto\|visual-tests' ; sed -n 56,62p e2e/flashcards-themes.visual.spec.ts; cat > /private/tmp/claude-501/-Users-thanhnguyen-Documents-Projects-nihongo-bjt/436eea3a-1300-4288-a74a-e7b4a3431add/scratchpad/dbg.spec.ts <<'EOF'
import { test } from "@playwright/test";
test("dbg", async ({ page }) => {
  const logs: string[] = [];
  page.on("console", (m) => logs.push(m.type() + ": " + m.text().slice(0, 200)));
  page.on("pageerror", (e) => logs.push("pageerror: " + e.message.slice(0, 300)));
  await page.goto("/visual-tests/flashcards?theme=ocean-calm");
  await page.waitForTimeout(4000);
  const btn = page.locator(".flashcard-theme-control[aria-pressed]").first();
  console.log("before", await btn.getAttribute("aria-pressed"));
  await btn.click();
  await page.waitForTimeout(500);
  console.log("after click", await btn.getAttribute("aria-pressed"));
  console.log(logs.slice(0, 10).join("\n"));
});
EOF
cp /private/tmp/claude-501/-Users-thanhnguyen-Documents-Projects-nihongo-bjt/436eea3a-1300-4288-a74a-e7b4a3431add/scratchpad/dbg.spec.ts e2e/zz-dbg.spec.ts; PLAYWRIGHT_SKIP_SERVER=1 pnpm exec playwright test e2e/zz-dbg.spec.ts --reporter=list 2>&1 | grep -v '^\s*$' | head -30; rm -f e2e/zz-dbg.spec.ts

